use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Extension granted by the graph's author: record the input received.
        state_rw::put("last-input", &feed_url);

        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: the one permitted fetch. A transport failure is a value (0 chars);
        // a host outside the allowlist traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: the contract requires `notified == true`, so retry briefly
        // and trap rather than emit an output that violates the ensures clause.
        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );
        let mut notified = false;
        for _ in 0..3 {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier did not accept the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
